-- Catches duplicate password authority, stale operation evidence and unsafe release.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_function('public','begin_invitation_completion',array['uuid','text','uuid','text','uuid','text'],'restricted password reservation exists');
select has_function('public','record_invitation_password',array['uuid','uuid','bigint','uuid','text','uuid','text','uuid','text'],'restricted password evidence exists');
select has_function('public','release_invitation_password',array['uuid','uuid','bigint','uuid','text','uuid','text','uuid','text'],'restricted password release exists');
select ok(not has_function_privilege('anon','public.begin_invitation_completion(uuid,text,uuid,text,uuid,text)','execute'),'anon cannot begin_invitation_completion');
select ok(not has_function_privilege('authenticated','public.begin_invitation_completion(uuid,text,uuid,text,uuid,text)','execute'),'authenticated cannot begin_invitation_completion');
select ok(has_function_privilege('service_role','public.begin_invitation_completion(uuid,text,uuid,text,uuid,text)','execute'),'server can begin_invitation_completion');
select ok(not has_function_privilege('anon','public.record_invitation_password(uuid,uuid,bigint,uuid,text,uuid,text,uuid,text)','execute'),'anon cannot record_invitation_password');
select ok(not has_function_privilege('authenticated','public.record_invitation_password(uuid,uuid,bigint,uuid,text,uuid,text,uuid,text)','execute'),'authenticated cannot record_invitation_password');
select ok(has_function_privilege('service_role','public.record_invitation_password(uuid,uuid,bigint,uuid,text,uuid,text,uuid,text)','execute'),'server can record_invitation_password');
select ok(not has_function_privilege('anon','public.release_invitation_password(uuid,uuid,bigint,uuid,text,uuid,text,uuid,text)','execute'),'anon cannot release_invitation_password');
select ok(not has_function_privilege('authenticated','public.release_invitation_password(uuid,uuid,bigint,uuid,text,uuid,text,uuid,text)','execute'),'authenticated cannot release_invitation_password');
select ok(has_function_privilege('service_role','public.release_invitation_password(uuid,uuid,bigint,uuid,text,uuid,text,uuid,text)','execute'),'server can release_invitation_password');
insert into auth.users(id,email,email_confirmed_at) values
 ('11000000-0000-4000-8000-000000000124','completion-admin@example.invalid',now()),
 ('22000000-0000-4000-8000-000000000124','completion@example.invalid',now());
insert into auth.sessions(id,user_id) values ('55000000-0000-4000-8000-000000000124','22000000-0000-4000-8000-000000000124');
insert into public.invitations(id,recipient_email,auth_user_id,invited_by_user_id,status,created_at) values
 ('33000000-0000-4000-8000-000000000124','completion@example.invalid','22000000-0000-4000-8000-000000000124','11000000-0000-4000-8000-000000000124','issued','2000-01-01');
insert into public.invitation_send_attempts(invitation_id,invitation_version,requested_by_user_id,kind,outcome,completed_at) values
 ('33000000-0000-4000-8000-000000000124',1,'11000000-0000-4000-8000-000000000124','initial','accepted',now());
select is(public.record_verified_invitation_setup('22000000-0000-4000-8000-000000000124','completion@example.invalid','55000000-0000-4000-8000-000000000124','https://complete.example.invalid',repeat('c',64),'33000000-0000-4000-8000-000000000124',1,null,null,'invite')->>'code','recorded','fixture establishes real setup');
create function pg_temp.authority() returns uuid language sql as $$ select id from public.invitation_setup_authorizations where invitation_id='33000000-0000-4000-8000-000000000124'; $$;
create function pg_temp.snapshot() returns jsonb language sql as $$ select jsonb_build_object(
 'invitation',(select to_jsonb(i) from public.invitations i where id='33000000-0000-4000-8000-000000000124'),
 'authority',(select to_jsonb(a) from public.invitation_setup_authorizations a where invitation_id='33000000-0000-4000-8000-000000000124'),
 'membership',(select to_jsonb(m) from public.memberships m where user_id='22000000-0000-4000-8000-000000000124')); $$;
create function pg_temp.begin_fixture(operation uuid default '77000000-0000-4000-8000-000000000124',digest text default repeat('c',64),subject uuid default '22000000-0000-4000-8000-000000000124',email text default 'COMPLETION@example.invalid',session uuid default '55000000-0000-4000-8000-000000000124',origin text default 'https://complete.example.invalid') returns jsonb language sql as $$ select public.begin_invitation_completion(operation,digest,subject,email,session,origin); $$;
create function pg_temp.finish_fixture(mode text default 'record',operation uuid default '77000000-0000-4000-8000-000000000124',invitation uuid default '33000000-0000-4000-8000-000000000124',version bigint default 1,authority uuid default pg_temp.authority(),digest text default repeat('c',64),subject uuid default '22000000-0000-4000-8000-000000000124',email text default 'COMPLETION@example.invalid',session uuid default '55000000-0000-4000-8000-000000000124',origin text default 'https://complete.example.invalid') returns jsonb language sql as $$ select case when mode='record' then public.record_invitation_password(operation,invitation,version,authority,digest,subject,email,session,origin) else public.release_invitation_password(operation,invitation,version,authority,digest,subject,email,session,origin) end; $$;
create function pg_temp.reject_begin(label text,operation uuid default '77000000-0000-4000-8000-000000000124',digest text default repeat('c',64),subject uuid default '22000000-0000-4000-8000-000000000124',email text default 'COMPLETION@example.invalid',session uuid default '55000000-0000-4000-8000-000000000124',origin text default 'https://complete.example.invalid') returns setof text language plpgsql as $$ declare before jsonb:=pg_temp.snapshot(); begin return next is(pg_temp.begin_fixture(operation,digest,subject,email,session,origin)->>'code','denied',label);return next is(pg_temp.snapshot(),before,label||' leaves records unchanged');end; $$;
create function pg_temp.reject_finish(label text,mode text default 'record',operation uuid default '77000000-0000-4000-8000-000000000124',invitation uuid default '33000000-0000-4000-8000-000000000124',version bigint default 1,authority uuid default pg_temp.authority(),digest text default repeat('c',64),subject uuid default '22000000-0000-4000-8000-000000000124',email text default 'COMPLETION@example.invalid',session uuid default '55000000-0000-4000-8000-000000000124',origin text default 'https://complete.example.invalid') returns setof text language plpgsql as $$ declare before jsonb:=pg_temp.snapshot(); begin return next is(pg_temp.finish_fixture(mode,operation,invitation,version,authority,digest,subject,email,session,origin)->>'code','denied',label);return next is(pg_temp.snapshot(),before,label||' leaves records unchanged');end; $$;
select * from pg_temp.reject_begin('null operation',operation=>null);
select * from pg_temp.reject_begin('null digest',digest=>null);
select * from pg_temp.reject_begin('null subject',subject=>null);
select * from pg_temp.reject_begin('null email',email=>null);
select * from pg_temp.reject_begin('null session',session=>null);
select * from pg_temp.reject_begin('null origin',origin=>null);
select * from pg_temp.reject_begin('wrong digest',digest=>repeat('x',64));
select * from pg_temp.reject_begin('wrong digest',digest=>repeat('d',64));
select * from pg_temp.reject_begin('wrong subject',subject=>'11000000-0000-4000-8000-000000000124');
select * from pg_temp.reject_begin('wrong email',email=>'other@example.invalid');
select * from pg_temp.reject_begin('wrong session',session=>'55000000-0000-4000-8000-000000000999');
select * from pg_temp.reject_begin('wrong origin',origin=>'https://other.invalid');
select * from pg_temp.reject_finish('cannot record without reservation');
select * from pg_temp.reject_finish('cannot release without reservation',mode=>'release');
savepoint denied_fixture;
update public.invitation_setup_authorizations set created_at=now()-interval '31 minutes',expires_at=now()-interval '1 minute';
select * from pg_temp.reject_begin('expired setup');
rollback to denied_fixture;
savepoint denied_fixture;
update auth.sessions set not_after=now()-interval '1 minute' where id='55000000-0000-4000-8000-000000000124';
select * from pg_temp.reject_begin('expired session');
rollback to denied_fixture;
savepoint denied_fixture;
update auth.users set banned_until=now()+interval '1 day' where id='22000000-0000-4000-8000-000000000124';
select * from pg_temp.reject_begin('active ban');
rollback to denied_fixture;
savepoint denied_fixture;
update auth.users set email_confirmed_at=null where id='22000000-0000-4000-8000-000000000124';
select * from pg_temp.reject_begin('unconfirmed');
rollback to denied_fixture;
savepoint denied_fixture;
update auth.users set is_anonymous=true where id='22000000-0000-4000-8000-000000000124';
select * from pg_temp.reject_begin('anonymous');
rollback to denied_fixture;
savepoint denied_fixture;
insert into public.memberships(user_id,role,status,disabled_at,disabled_reason) values ('22000000-0000-4000-8000-000000000124','member','disabled',now(),'Owned fixture');
select * from pg_temp.reject_begin('disabled membership');
rollback to denied_fixture;
savepoint denied_fixture;
insert into public.memberships(user_id,role,status) values ('22000000-0000-4000-8000-000000000124','admin','active');
select * from pg_temp.reject_begin('existing active admin membership');
rollback to denied_fixture;
set local role service_role;
select is(public.begin_invitation_completion('77000000-0000-4000-8000-000000000124',repeat('c',64),'22000000-0000-4000-8000-000000000124','completion@example.invalid','55000000-0000-4000-8000-000000000124','https://complete.example.invalid')->>'code','reserved','server reserves an old eligible invitation');
reset role;
select is((select count(*) from public.memberships where user_id='22000000-0000-4000-8000-000000000124'),0::bigint,'reservation grants no membership');
create temporary table reserved_state as select pg_temp.snapshot() as value;
select is(pg_temp.begin_fixture(operation=>'77000000-0000-4000-8000-000000000125')->>'code','busy','concurrent operation cannot repeat password');
select is(pg_temp.begin_fixture()->>'code','busy','repeated operation cannot repeat password');
select is(pg_temp.snapshot(),(select value from reserved_state),'busy calls do not change reservation');
savepoint abandoned;
update public.invitation_setup_authorizations set password_started_at=now()-interval '31 seconds' where id=pg_temp.authority();
select is(pg_temp.begin_fixture()->>'code','renew_required','abandoned operation requires renewal rather than lease takeover');
select ok((select password_operation_id is not null from public.invitation_setup_authorizations where id=pg_temp.authority()),'abandoned reservation remains owned');
rollback to abandoned;
select * from pg_temp.reject_finish('record null operation',mode=>'record',operation=>null);
select * from pg_temp.reject_finish('record null invitation',mode=>'record',invitation=>null);
select * from pg_temp.reject_finish('record null version',mode=>'record',version=>null);
select * from pg_temp.reject_finish('record null authority',mode=>'record',authority=>null);
select * from pg_temp.reject_finish('record null digest',mode=>'record',digest=>null);
select * from pg_temp.reject_finish('record null subject',mode=>'record',subject=>null);
select * from pg_temp.reject_finish('record null email',mode=>'record',email=>null);
select * from pg_temp.reject_finish('record null session',mode=>'record',session=>null);
select * from pg_temp.reject_finish('record null origin',mode=>'record',origin=>null);
select * from pg_temp.reject_finish('record wrong operation',mode=>'record',operation=>'77000000-0000-4000-8000-000000000125');
select * from pg_temp.reject_finish('record wrong version',mode=>'record',version=>2);
select * from pg_temp.reject_finish('record wrong authority',mode=>'record',authority=>'66000000-0000-4000-8000-000000000999');
select * from pg_temp.reject_finish('record wrong digest',mode=>'record',digest=>repeat('d',64));
select * from pg_temp.reject_finish('record wrong subject',mode=>'record',subject=>'11000000-0000-4000-8000-000000000124');
select * from pg_temp.reject_finish('record wrong email',mode=>'record',email=>'other@example.invalid');
select * from pg_temp.reject_finish('record wrong session',mode=>'record',session=>'55000000-0000-4000-8000-000000000999');
select * from pg_temp.reject_finish('record wrong origin',mode=>'record',origin=>'https://other.invalid');
select * from pg_temp.reject_finish('release null operation',mode=>'release',operation=>null);
select * from pg_temp.reject_finish('release null invitation',mode=>'release',invitation=>null);
select * from pg_temp.reject_finish('release null version',mode=>'release',version=>null);
select * from pg_temp.reject_finish('release null authority',mode=>'release',authority=>null);
select * from pg_temp.reject_finish('release null digest',mode=>'release',digest=>null);
select * from pg_temp.reject_finish('release null subject',mode=>'release',subject=>null);
select * from pg_temp.reject_finish('release null email',mode=>'release',email=>null);
select * from pg_temp.reject_finish('release null session',mode=>'release',session=>null);
select * from pg_temp.reject_finish('release null origin',mode=>'release',origin=>null);
select * from pg_temp.reject_finish('release wrong operation',mode=>'release',operation=>'77000000-0000-4000-8000-000000000125');
select * from pg_temp.reject_finish('release wrong version',mode=>'release',version=>2);
select * from pg_temp.reject_finish('release wrong authority',mode=>'release',authority=>'66000000-0000-4000-8000-000000000999');
select * from pg_temp.reject_finish('release wrong digest',mode=>'release',digest=>repeat('d',64));
select * from pg_temp.reject_finish('release wrong subject',mode=>'release',subject=>'11000000-0000-4000-8000-000000000124');
select * from pg_temp.reject_finish('release wrong email',mode=>'release',email=>'other@example.invalid');
select * from pg_temp.reject_finish('release wrong session',mode=>'release',session=>'55000000-0000-4000-8000-000000000999');
select * from pg_temp.reject_finish('release wrong origin',mode=>'release',origin=>'https://other.invalid');
savepoint stale;
update public.invitations set status='issued',verified_user_id=null,verified_at=null,setup_authorization_id=null,password_established_at=null where id='33000000-0000-4000-8000-000000000124';
select * from pg_temp.reject_finish('stale reservation cannot record');
select * from pg_temp.reject_finish('stale reservation cannot release',mode=>'release');
rollback to stale;
savepoint expiry;
update public.invitation_setup_authorizations set created_at=now()-interval '31 minutes',expires_at=now()-interval '1 minute' where id=pg_temp.authority();
select * from pg_temp.reject_finish('expired reservation cannot record');
select * from pg_temp.reject_finish('expired reservation cannot release',mode=>'release');
rollback to expiry;
select is(pg_temp.finish_fixture(mode=>'release')->>'code','released','known failure can safely release matching reservation');
select ok((select password_operation_id is null and password_started_at is null from public.invitation_setup_authorizations where id=pg_temp.authority()),'release clears only reservation');
select is(pg_temp.begin_fixture()->>'code','reserved','same authorized attempt can retry after safe release');
select is(pg_temp.finish_fixture()->>'code','recorded','matching observed success records evidence');
select ok((select status='password_established' and password_established_at>=verified_at and updated_at>=password_established_at from public.invitations where id='33000000-0000-4000-8000-000000000124'),'password evidence timestamp is ordered');
create temporary table password_state as select pg_temp.snapshot() as value;
select is(pg_temp.finish_fixture()->>'code','recorded','recorded success is idempotent');
select is(pg_temp.finish_fixture(mode=>'release')->>'code','recorded','lost record response cannot clear success');
select is(pg_temp.snapshot(),(select value from password_state),'record/release preserve evidence');
select is(pg_temp.begin_fixture()->>'code','password_established','password evidence skips mutation');
select * from pg_temp.reject_finish('wrong operation cannot assert recorded success',operation=>'77000000-0000-4000-8000-000000000125');
select is(public.redeem_invitation('33000000-0000-4000-8000-000000000124',1,pg_temp.authority(),repeat('c',64),'22000000-0000-4000-8000-000000000124','completion@example.invalid','55000000-0000-4000-8000-000000000124','https://complete.example.invalid')->>'code','redeemed','recorded evidence feeds existing redemption');
update public.memberships set status='disabled',disabled_at=now(),disabled_reason='Owned fixture' where user_id='22000000-0000-4000-8000-000000000124';
create temporary table completed_state as select pg_temp.snapshot() as value;
select is(pg_temp.begin_fixture()->>'code','redeemed','matching completed context is historical only');
select is(pg_temp.snapshot(),(select value from completed_state),'historical lookup cannot change disabled membership');
select * from finish();
rollback;
